class txn {
  std::vector<std::pair<std::shared_ptr<const Cell>, Cell>> readset;
  std::vector<std::pair<std::shared_ptr<Cell>, Cell>>        writeset;
public:
  Cell& read(const std::shared_ptr<const Cell>& c) {
    readset.emplace_back(c, *c);                 // snapshot for undo + conflict
    return *c;
  }
  void write(const std::shared_ptr<Cell>& c, Cell v) { writeset.emplace_back(c, std::move(v)); }
  bool commit() {                                // validate, then publish as one step
    for (auto& [c, seen] : readset)
      if (c->version != seen.version) return false;   // caller replays the block
    for (auto& [c, v] : writeset) { v.version = c->version + 1; c->store(v); }
    return true;
  }
  ~txn() { /* uncommitted writes are simply dropped */ }
};
